#include <gtest/gtest.h>

#include <vector>

#include "billing/meter.h"
#include "billing/tariff.h"

TEST(TariffCharacterization, TieredPriceFirstTier) {
    EXPECT_EQ(0u, billing::tieredPrice(0));
    EXPECT_EQ(10u, billing::tieredPrice(1));
    EXPECT_EQ(500u, billing::tieredPrice(50));
    EXPECT_EQ(1000u, billing::tieredPrice(100));
}

TEST(TariffCharacterization, TieredPriceSecondTier) {
    EXPECT_EQ(1008u, billing::tieredPrice(101));
    EXPECT_EQ(2600u, billing::tieredPrice(300));
    EXPECT_EQ(4000u, billing::tieredPrice(500));
}

TEST(TariffCharacterization, TieredPriceThirdTier) {
    EXPECT_EQ(4205u, billing::tieredPrice(501));
    EXPECT_EQ(6700u, billing::tieredPrice(1000));
}

TEST(TariffCharacterization, LoyaltyDiscountSteps) {
    EXPECT_EQ(0u, billing::loyaltyDiscount(0));
    EXPECT_EQ(0u, billing::loyaltyDiscount(1));
    EXPECT_EQ(5u, billing::loyaltyDiscount(2));
    EXPECT_EQ(5u, billing::loyaltyDiscount(4));
    EXPECT_EQ(10u, billing::loyaltyDiscount(5));
    EXPECT_EQ(10u, billing::loyaltyDiscount(9));
    EXPECT_EQ(15u, billing::loyaltyDiscount(10));
    EXPECT_EQ(15u, billing::loyaltyDiscount(30));
}

TEST(TariffCharacterization, ApplyDiscountRoundsHalfUp) {
    EXPECT_EQ(1000u, billing::applyDiscount(1000, 0));
    EXPECT_EQ(850u, billing::applyDiscount(1000, 15));
    EXPECT_EQ(899u, billing::applyDiscount(999, 10));
    EXPECT_EQ(3u, billing::applyDiscount(5, 50));
    EXPECT_EQ(2u, billing::applyDiscount(3, 50));
    EXPECT_EQ(1u, billing::applyDiscount(1, 50));
}

TEST(TariffCharacterization, ApplyDiscountOfAHundredPercentOrMore) {
    EXPECT_EQ(0u, billing::applyDiscount(1000, 100));
    EXPECT_EQ(0u, billing::applyDiscount(1000, 150));
    EXPECT_EQ(0u, billing::applyDiscount(0, 20));
}

TEST(TariffCharacterization, TotalWithoutAReachedCap) {
    billing::CentsList none;
    EXPECT_EQ(0u, billing::total(none, 0));
    billing::CentsList charges;
    charges.push_back(100);
    charges.push_back(200);
    charges.push_back(300);
    EXPECT_EQ(600u, billing::total(charges, 0));
    EXPECT_EQ(600u, billing::total(charges, 1000));
}

TEST(TariffCharacterization, TotalStopsAtTheCap) {
    billing::CentsList charges;
    charges.push_back(100);
    charges.push_back(200);
    charges.push_back(300);
    EXPECT_EQ(250u, billing::total(charges, 250));
    EXPECT_EQ(300u, billing::total(charges, 300));
    billing::CentsList two;
    two.push_back(100);
    two.push_back(200);
    EXPECT_EQ(300u, billing::total(two, 300));
}

TEST(MeterCharacterization, StartsWithNothingRecorded) {
    billing::Meter meter(100);
    EXPECT_EQ(0u, meter.consumption());
    EXPECT_EQ(0u, meter.readings());
    EXPECT_FALSE(meter.rolledOver());
}

TEST(MeterCharacterization, RecordsReadingsAndRollover) {
    billing::Meter meter(100);
    meter.record(150);
    EXPECT_EQ(50u, meter.consumption());
    EXPECT_EQ(1u, meter.readings());
    meter.record(150);
    EXPECT_EQ(50u, meter.consumption());
    EXPECT_EQ(2u, meter.readings());
    EXPECT_FALSE(meter.rolledOver());
    meter.record(120);
    EXPECT_TRUE(meter.rolledOver());
    EXPECT_EQ(50u, meter.consumption());
    EXPECT_EQ(2u, meter.readings());
    meter.record(200);
    EXPECT_EQ(100u, meter.consumption());
    EXPECT_EQ(3u, meter.readings());
    EXPECT_TRUE(meter.rolledOver());
}
